#!/usr/bin/env python3
"""
Changelog & Version Manager for Monorepo
Generates changelogs and updates version numbers based on Git history.
"""

import os
import re
import subprocess
from collections import defaultdict
from datetime import datetime
from pathlib import Path


def run_git_command(args):
    """Run a git command and return output."""
    result = subprocess.run(
        ['git'] + args,
        capture_output=True,
        text=True,
        cwd=os.getcwd()
    )
    return result.stdout.strip()


def get_last_tag():
    """Get the most recent git tag, or None if no tags exist."""
    tags = run_git_command(['tag', '--list']).split('\n')
    if tags:
        # Get the latest tag (sorted by version, but we'll just take the last one)
        # Actually, we want commits since the most recent tag
        return sorted(tags, reverse=True)[0]
    return None


def get_commits_since_tag(tag):
    """Get commit hashes from tag to HEAD."""
    if tag is None:
        return run_git_command(['rev-parse', 'HEAD'])
    # Get commits from tag to HEAD (exclusive of tag, inclusive of HEAD)
    return run_git_command(['rev-parse', f'{tag}..HEAD'])


def parse_commit_message(message):
    """
    Parse commit message in format: type(scope): description
    Returns (type, scope, description) or None if invalid.
    """
    # Pattern: type(scope): description
    pattern = r'^([a-z]+)\(([a-z0-9-]+)\):\s*(.+)$'
    match = re.match(pattern, message.strip())
    if match:
        return match.group(1), match.group(2), match.match(2)
    return None, None, None


def get_modified_files_in_package(commit_hash, package_path):
    """Check if a commit modified files in a specific package path."""
    # Get the diff for this commit
    result = subprocess.run(
        ['git', 'show', '--name-only', '--format=', commit_hash],
        capture_output=True,
        text=True,
        cwd=os.getcwd()
    )
    files = result.stdout.strip().split('\n') if result.stdout.strip() else []

    # Check if any file is in the package directory
    for f in files:
        if f.startswith(package_path + '/') or f == package_path:
            return True
    return False


def get_package_from_file(filepath):
    """Given a file path, return the package name if it's in packages/<name>/."""
    if filepath.startswith('packages/'):
        parts = filepath.split('/')
        if len(parts) >= 2:
            return parts[1]  # packages/<name>/
    return None


def get_commits_for_packages():
    """
    Get commits from last tag to HEAD, and map each to packages.
    Returns dict: package_name -> list of (commit_hash, message, files)
    """
    tag = get_last_tag()
    commits_str = get_commits_since_tag(tag)

    if not commits_str:
        return {}

    commit_hashes = commits_str.split('\n')

    # Get all modified files for all commits
    all_files_by_commit = {}
    for commit_hash in commit_hashes:
        if not commit_hash:
            continue
        result = subprocess.run(
            ['git', 'show', '--name-only', '--format=', commit_hash],
            capture_output=True,
            text=True,
            cwd=os.getcwd()
        )
        files = [f for f in result.stdout.strip().split('\n') if f]
        all_files_by_commit[commit_hash] = files

    # Get commit messages
    commit_messages = {}
    for commit_hash in commit_hashes:
        if not commit_hash:
            continue
        result = subprocess.run(
            ['git', 'log', '-1', '--format=%s', commit_hash],
            capture_output=True,
            text=True,
            cwd=os.getcwd()
        )
        commit_messages[commit_hash] = result.stdout.strip()

    # Map commits to packages
    packages_commits = defaultdict(list)
    for commit_hash in commit_hashes:
        if not commit_hash:
            continue
        files = all_files_by_commit.get(commit_hash, [])
        if not files:
            continue

        # Find which package this commit affects
        for f in files:
            pkg_name = get_package_from_file(f)
            if pkg_name:
                packages_commits[pkg_name].append((commit_hash, commit_messages[commit_hash], files))
                break  # Only need to know it affects this package once

    return dict(packages_commits)


def determine_version_bump(commit_message):
    """
    Determine version bump type from commit message.
    Returns: 'MAJOR', 'MINOR', 'PATCH', or None.
    """
    # Check for BREAKING CHANGE in commit body (not just message line)
    # Get full commit
    result = subprocess.run(
        ['git', 'log', '-1', '--format=%B', commit_message],
        capture_output=True,
        text=True,
        cwd=os.getcwd()
    )
    body = result.stdout.strip()

    # Check for BREAKING CHANGE
    if 'BREAKING CHANGE' in body:
        return 'MAJOR'

    # Parse the short message
    # Format: type(scope): description
    pattern = r'^([a-z]+)\([^)]+\):\s*(.+)$'
    match = re.match(pattern, commit_message.strip())
    if match:
        commit_type = match.group(1)
        if commit_type == 'feat':
            return 'MINOR'
        elif commit_type == 'fix':
            return 'PATCH'

    return None


def parse_deps_txt(package_path):
    """Parse deps.txt file for a package, return list of dependency names."""
    deps_file = os.path.join(package_path, 'deps.txt')
    if not os.path.exists(deps_file):
        return []

    deps = []
    with open(deps_file, 'r') as f:
        for line in f:
            line = line.strip()
            if line and not line.startswith('#'):
                deps.append(line)
    return deps


def build_dependency_graph(packages_dir):
    """
    Build a dependency graph.
    Returns dict: package_name -> list of packages that depend on it.
    (i.e., if pkg-b depends on pkg-a, then graph['pkg-a'] includes 'pkg-b')
    """
    deps = {}  # package -> list of packages that depend on it
    reverse_deps = defaultdict(list)  # package -> list of packages it depends on

    # Find all packages
    packages = []
    for item in os.listdir(packages_dir):
        item_path = os.path.join(packages_dir, item)
        if os.path.isdir(item_path):
            packages.append(item)

    # Build dependency relationships
    for pkg in packages:
        pkg_path = os.path.join(packages_dir, pkg)
        dep_files = parse_deps_txt(pkg_path)
        deps[pkg] = dep_files  # packages that pkg depends on
        for dep in dep_files:
            reverse_deps[dep].append(pkg)  # packages that depend on pkg

    return reverse_deps  # map: package -> list of packages that depend on it


def bump_version(version_str, bump_type):
    """
    Bump version string according to bump_type (MAJOR, MINOR, PATCH).
    Returns new version string.
    """
    parts = version_str.split('.')
    if len(parts) != 3:
        return version_str  # Invalid version format

    major, minor, patch = int(parts[0]), int(parts[1]), int(parts[2])

    if bump_type == 'MAJOR':
        major += 1
        minor = 0
        patch = 0
    elif bump_type == 'MINOR':
        minor += 1
        patch = 0
    elif bump_type == 'PATCH':
        patch += 1

    return f"{major}.{minor}.{patch}"


def get_initial_version():
    """Get initial version (from first VERSION file or default 1.0.0)."""
    # Try to read from any VERSION file
    try:
        result = subprocess.run(
            ['git', 'show', ':packages/utils/VERSION'],
            capture_output=True,
            text=True,
            cwd=os.getcwd()
        )
        if result.returncode == 0:
            return result.stdout.strip()
    except:
        pass
    return '1.0.0'


def process_packages(packages_dir):
    """
    Main logic: process all packages, compute version bumps, propagate dependencies.
    Returns dict: package_name -> {version, changelog_entries, bump_reason}
    """
    # Step 1: Get commits per package
    packages_commits = get_commits_for_packages()

    # Step 2: Build dependency graph (reverse: who depends on whom)
    reverse_deps = build_dependency_graph(packages_dir)

    # Step 3: Determine direct bumps from commits
    # Direct bumps: based on commit types
    direct_bumps = {}  # package -> bump_type (or None)
    for pkg, commits in packages_commits.items():
        bumps = []
        for commit_hash, msg, files in commits:
            bump = determine_version_bump(msg)
            if bump:
                bumps.append(bump)
        # Take highest bump
        if bumps:
            if 'MAJOR' in bumps:
                direct_bumps[pkg] = 'MAJOR'
            elif 'MINOR' in bumps:
                direct_bumps[pkg] = 'MINOR'
            else:
                direct_bumps[pkg] = 'PATCH'

    # Step 4: Initialize version tracking
    # Get current versions from VERSION files
    current_versions = {}
    for item in os.listdir(packages_dir):
        item_path = os.path.join(packages_dir, item)
        if os.path.isdir(item_path):
            version_file = os.path.join(item_path, 'VERSION')
            if os.path.exists(version_file):
                with open(version_file, 'r') as f:
                    current_versions[item] = f.read().strip()
            else:
                current_versions[item] = '1.0.0'
        else:
            current_versions[item] = '1.0.0'

    # Step 5: Propagate dependency bumps
    # Start with packages that have direct bumps
    bumped_packages = set()
    for pkg in direct_bumps:
        bumped_packages.add(pkg)

    # Propagate through dependency graph (BFS/iterative)
    changed = True
    while changed:
        changed = False
        for pkg in list(bumped_packages):
            # Find all packages that depend on pkg
            dependents = reverse_deps.get(pkg, [])
            for dep_pkg in dependents:
                if dep_pkg not in bumped_packages:
                    bumped_packages.add(dep_pkg)
                    changed = True

    # Step 6: Compute final versions and collect changelog data
    results = {}
    for pkg in current_versions:
        version = current_versions[pkg]

        # Determine if this package has direct commits
        has_direct_commits = pkg in packages_commits

        # Determine bump type
        if pkg in direct_bumps:
            bump_type = direct_bumps[pkg]
        elif pkg in bumped_packages and pkg not in direct_bumps:
            # Bumped only due to dependencies
            bump_type = 'PATCH'
        else:
            bump_type = None

        if bump_type:
            new_version = bump_version(version, bump_type)
            results[pkg] = {
                'version': new_version,
                'bump_type': bump_type,
                'has_direct_commits': has_direct_commits
            }
        else:
            results[pkg] = {
                'version': version,
                'bump_type': None,
                'has_direct_commits': has_direct_commits
            }

    return results, packages_commits, reverse_deps, direct_bumps


def generate_changelog(pkg_name, version, packages_commits, reverse_deps, direct_bumps):
