    print("Changelog generation complete.")
    return 0


def generate_changelog_content(pkg_name, new_version, packages_commits, direct_bumps, bumped_packages):
    """Generate CHANGELOG.md content for a package."""
    lines = []
    lines.append(f"## {new_version} ({datetime.now().strftime('%Y-%m-%d')})")

    commits = packages_commits.get(pkg_name, [])

    features = []
    fixes = []

    if commits:
        for commit_hash, msg, files in commits:
            match = re.match(r'^([a-z]+)\([^)]+\):\s*(.+)$', msg.strip())
            if match:
                commit_type = match.group(1)
                description = match.group(2)
                if commit_type == 'feat':
                    features.append(description)
                elif commit_type == 'fix':
                    fixes.append(description)

    # Check if this package was bumped only due to dependencies
    # (i.e., not in direct_bumps but in bumped_packages)
    is_dep_only = pkg_name not in direct_bumps and pkg_name in bumped_packages

    if is_dep_only:
