    """Get the most recent git tag."""
    tags_output = run_git_command(['tag', '--list'])
    if not tags_output:
        return None
    tags = [t for t in tags_output.split('\n') if t]
    if not tags:
        return None
    # Get latest tag - sort by version number
    # Simple approach: take the last one from git's output (usually sorted)
    # But to be safe, let's use git describe or just pick one
    return tags[-1] if tags else None


def get_commits_range(tag):
    """Get commit hashes from tag to HEAD (or all commits if no tag)."""
    if tag is None:
        # Get all commits from HEAD (empty range means all history from HEAD)
        # Actually, we want from beginning of history to HEAD
        # Use git log --oneline --all or get all refs
        commits = run_git_command(['log', '--oneline', '--reverse'])
        # This gives all commits, but we want to process them
        # Better: get commit hashes
        return run_git_command(['rev-list', 'HEAD'])
    else:
        # Get commits from tag to HEAD (exclusive of tag)
        return run_git_command(['rev-list', f'{tag}..HEAD'])


def get_commit_message(commit_hash):
    """Get the commit message (subject line) for a commit."""
    return run_git_command(['log', '-1', '--format=%s', commit_hash])


def get_commit_files(commit_hash):
    """Get list of files changed in a commit."""
    result = subprocess.run(
        ['git', 'show', '--name-only', '--format=', commit_hash],
        capture_output=True,
        text=True,
        cwd=os.getcwd()
    )
    files = [f for f in result.stdout.strip().split('\n') if f]
    return files


