    """Given a file path, return the package name if in packages/<name>/."""
    if filepath.startswith('packages/'):
        parts = filepath.split('/')
        if len(parts) >= 3:  # packages/name/...
            return parts[1]
    return None


def get_commits_by_package():
    """
    Get commits from last tag to HEAD, grouped by package.
    Returns dict: package_name -> list of (commit_hash, message, files)
    """
    tag = get_last_tag()
    commit_hashes = get_commits_range(tag)

    if not commit_hashes:
        return {}

    # Group commits by package
    packages_commits = defaultdict(list)

    for commit_hash in commit_hashes.split('\n'):
        if not commit_hash:
            continue

        message = get_commit_message(commit_hash)
        files = get_commit_files(commit_hash)

